+
+    .error-message {
+      min-height: 1.4em;
+      color: var(--danger);
+      font-weight: 700;
+    }
+
+    button {
+      width: 100%;
+      margin-top: 0.4rem;
+      padding: 0.95rem 1.2rem;
+      border: 0;
+      border-radius: 999px;
+      background: linear-gradient(135deg, var(--accent), #5bd6ff);
+      color: #07101f;
+      cursor: pointer;
+      font: inherit;
+      font-weight: 800;
+      transition: transform 150ms ease, filter 150ms ease;
+    }
+
+    button:hover {
+      filter: brightness(1.08);
+      transform: translateY(-1px);
+    }
+
+    button:focus-visible {
+      outline: 0.2rem solid var(--accent-hover);
+      outline-offset: 0.2rem;
