+<body>
+  <main>
+    <section class="contact-card" aria-labelledby="support-title">
+      <h1 id="support-title">Contact Support</h1>
+      <p class="intro">Tell us how to reach you and our support team will follow up soon.</p>
+
+      <form id="support-form" novalidate>
+        <div class="form-field">
+          <label for="full-name">Full name <span aria-hidden="true">*</span></label>
+          <input
+            type="text"
+            id="full-name"
+            name="fullName"
+            autocomplete="name"
+            placeholder="Alex Morgan"
+            required
+            aria-describedby="full-name-error"
+          >
+          <p class="error-message" id="full-name-error" aria-live="polite"></p>
+        </div>
+
+        <div class="form-field">
+          <label for="email">Email address <span aria-hidden="true">*</span></label>
+          <input
+            type="email"
+            id="email"
+            name="email"
+            autocomplete="email"
+            placeholder="alex@example.com"
+            required
+            aria-describedby="email-error"
+          >
+          <p class="error-message" id="email-error" aria-live="polite"></p>
+        </div>
+
+        <div class="form-field">
+          <label for="phone">Phone number</label>
+          <input
+            type="tel"
+            id="phone"
+            name="phone"
+            autocomplete="tel"
+            placeholder="(555) 123-4567"
+            aria-describedby="phone-helper phone-error"
+          >
+          <p class="helper-text" id="phone-helper">Optional. Use a 10-digit US number, such as (555) 123-4567.</p>
+          <p class="error-message" id="phone-error" aria-live="polite"></p>
+        </div>
+
+        <button type="submit">Submit request</button>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.querySelector("#support-form");
+    const fields = {
+      fullName: {
+        input: document.querySelector("#full-name"),
+        error: document.querySelector("#full-name-error"),
+        validate(value) {
+          return value.trim() ? "" : "Enter your full name.";
+        },
+      },
+      email: {
+        input: document.querySelector("#email"),
+        error: document.querySelector("#email-error"),
+        validate(value) {
+          const trimmed = value.trim();
+          const isValidEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed);
+
+          if (!trimmed) {
+            return "Enter your email address.";
+          }
+
+          return isValidEmail ? "" : "Enter a valid email address, such as alex@example.com.";
+        },
+      },
+      phone: {
+        input: document.querySelector("#phone"),
+        error: document.querySelector("#phone-error"),
+        validate(value) {
+          const trimmed = value.trim();
+
+          if (!trimmed) {
+            return "";
+          }
+
+          return /^\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}$/.test(trimmed)
+            ? ""
+            : "Enter a 10-digit phone number, such as (555) 123-4567.";
+        },
+      },
+    };
+
+    function setError(field, message) {
+      field.error.textContent = message;
+      field.input.setAttribute("aria-invalid", message ? "true" : "false");
+    }
+
+    function validateField(field) {
+      const message = field.validate(field.input.value);
+      setError(field, message);
+      return !message;
+    }
+
+    Object.values(fields).forEach((field) => {
+      field.input.addEventListener("blur", () => validateField(field));
+      field.input.addEventListener("input", () => {
+        if (field.input.getAttribute("aria-invalid") === "true") {
+          validateField(field);
+        }
+      });
+    });
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+
+      const firstInvalidField = Object.values(fields).find((field) => !validateField(field));
+
+      if (firstInvalidField) {
+        firstInvalidField.input.focus();
+        return;
+      }
+
+      form.reset();
+      Object.values(fields).forEach((field) => setError(field, ""));
+    });
+  </script>
+</body>
+</html>
