  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #141b2f;
      --panel-border: #293552;
      --text: #f4f7fb;
      --muted: #aab6cf;
      --accent: #7c5cff;
      --accent-hover: #9278ff;
      --danger: #ff8a8a;
      --input: #0f1628;
      --input-focus: #1b2440;
      --shadow: rgba(0, 0, 0, 0.36);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 2rem;
      background:
        radial-gradient(circle at top left, rgba(124, 92, 255, 0.24), transparent 34rem),
        linear-gradient(135deg, #080c18 0%, var(--bg) 55%, #10172a 100%);
      color: var(--text);
      font-family: Arial, Helvetica, sans-serif;
      line-height: 1.5;
    }

    main {
      width: min(100%, 34rem);
    }

    .contact-card {
      padding: clamp(1.5rem, 4vw, 2.5rem);
      border: 1px solid var(--panel-border);
      border-radius: 1.25rem;
      background: rgba(20, 27, 47, 0.92);
      box-shadow: 0 1.25rem 3.75rem var(--shadow);
      backdrop-filter: blur(10px);
    }

    h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(2rem, 5vw, 2.75rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 2rem;
      color: var(--muted);
    }

    .form-field {
      margin-bottom: 1.25rem;
    }

    label {
      display: block;
      margin-bottom: 0.45rem;
      font-weight: 700;
    }

    input {
      width: 100%;
      padding: 0.9rem 1rem;
      border: 1px solid var(--panel-border);
      border-radius: 0.75rem;
      background: var(--input);
      color: var(--text);
      font: inherit;
      transition: border-color 150ms ease, box-shadow 150ms ease, background 150ms ease;
    }

    input::placeholder {
      color: #7f8aa4;
      opacity: 1;
    }

    input:focus {
      outline: none;
      border-color: var(--accent);
      background: var(--input-focus);
      box-shadow: 0 0 0 0.2rem rgba(124, 92, 255, 0.28);
    }

    input[aria-invalid="true"] {
      border-color: var(--danger);
    }

    .helper-text,
    .error-message {
      margin: 0.4rem 0 0;
      font-size: 0.92rem;
    }

    .helper-text {
      color: var(--muted);
    }

    .error-message {
      min-height: 1.4em;
      color: var(--danger);
      font-weight: 700;
    }

    button {
      width: 100%;
      margin-top: 0.4rem;
      padding: 0.95rem 1.2rem;
      border: 0;
      border-radius: 999px;
      background: linear-gradient(135deg, var(--accent), #5bd6ff);
      color: #07101f;
      cursor: pointer;
      font: inherit;
      font-weight: 800;
      transition: transform 150ms ease, filter 150ms ease;
    }

    button:hover {
      filter: brightness(1.08);
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 0.2rem solid var(--accent-hover);
      outline-offset: 0.2rem;
    }
  </style>
</head>
<body>
  <main>
    <section class="contact-card" aria-labelledby="support-title">
      <h1 id="support-title">Contact Support</h1>
      <p class="intro">Tell us how to reach you and our support team will follow up soon.</p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">Full name <span aria-hidden="true">*</span></label>
          <input
            type="text"
            id="full-name"
            name="fullName"
            autocomplete="name"
            placeholder="Alex Morgan"
            required
            aria-describedby="full-name-error"
          >
          <p class="error-message" id="full-name-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="email">Email address <span aria-hidden="true">*</span></label>
          <input
            type="email"
            id="email"
            name="email"
            autocomplete="email"
            placeholder="alex@example.com"
            required
            aria-describedby="email-error"
          >
          <p class="error-message" id="email-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="phone">Phone number</label>
          <input
            type="tel"
            id="phone"
            name="phone"
            autocomplete="tel"
            placeholder="(555) 123-4567"
            aria-describedby="phone-helper phone-error"
          >
          <p class="helper-text" id="phone-helper">Optional. Use a 10-digit US number, such as (555) 123-4567.</p>
          <p class="error-message" id="phone-error" aria-live="polite"></p>
        </div>

        <button type="submit">Submit request</button>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#support-form");
    const fields = {
      fullName: {
        input: document.querySelector("#full-name"),
        error: document.querySelector("#full-name-error"),
        validate(value) {
          return value.trim() ? "" : "Enter your full name.";
        },
      },
      email: {
        input: document.querySelector("#email"),
        error: document.querySelector("#email-error"),
        validate(value) {
          const trimmed = value.trim();
          const isValidEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed);

          if (!trimmed) {
            return "Enter your email address.";
          }

          return isValidEmail ? "" : "Enter a valid email address, such as alex@example.com.";
        },
      },
      phone: {
        input: document.querySelector("#phone"),
        error: document.querySelector("#phone-error"),
        validate(value) {
          const trimmed = value.trim();

          if (!trimmed) {
            return "";
          }

          return /^\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}$/.test(trimmed)
            ? ""
            : "Enter a 10-digit phone number, such as (555) 123-4567.";
        },
      },
    };

    function setError(field, message) {
      field.error.textContent = message;
      field.input.setAttribute("aria-invalid", message ? "true" : "false");
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      setError(field, message);
      return !message;
    }

    Object.values(fields).forEach((field) => {
      field.input.addEventListener("blur", () => validateField(field));
      field.input.addEventListener("input", () => {
        if (field.input.getAttribute("aria-invalid") === "true") {
          validateField(field);
        }
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const firstInvalidField = Object.values(fields).find((field) => !validateField(field));

      if (firstInvalidField) {
        firstInvalidField.input.focus();
        return;
      }

      form.reset();
      Object.values(fields).forEach((field) => setError(field, ""));
    });
  </script>
</body>
</html>
